'use client';
import { useAuth } from '../context/AuthContext';
import { Trash2, Calendar, Clock, Briefcase } from 'lucide-react';
import api from '../utils/api';

export default function ShiftTable({ shifts, onDelete }) {
    const { user } = useAuth();

    const handleDelete = async (id) => {
        if (confirm('Are you sure you want to delete this shift?')) {
            try {
                await api.delete(`/shifts/${id}`);
                if (onDelete) onDelete();
            } catch (err) {
                alert('Failed to delete shift');
            }
        }
    };

    if (shifts.length === 0) {
        return (
            <div className="glass-card p-12 text-center text-gray-400">
                <Calendar className="w-12 h-12 mx-auto mb-4 opacity-50" />
                <p>No shifts found.</p>
            </div>
        );
    }

    return (
        <div className="glass-card overflow-hidden">
            <div className="table-container">
                <table>
                    <thead>
                        <tr>
                            <th>Employee</th>
                            <th>Date</th>
                            <th>Time</th>
                            <th>Duration</th>
                            {user?.role === 'admin' && <th className="text-right">Actions</th>}
                        </tr>
                    </thead>
                    <tbody>
                        {shifts.map(shift => {
                            // Calculate duration for display
                            const start = new Date(`2000-01-01T${shift.startTime}`);
                            const end = new Date(`2000-01-01T${shift.endTime}`);
                            const diff = (end - start) / (1000 * 60 * 60);

                            return (
                                <tr key={shift._id} className="hover:bg-white/5 transition-colors">
                                    <td>
                                        <div className="flex flex-col">
                                            <span className="font-semibold text-white">{shift.employeeId.name}</span>
                                            <span className="text-xs text-gray-400">{shift.employeeId.department} | {shift.employeeId.employeeCode}</span>
                                        </div>
                                    </td>
                                    <td>
                                        <div className="flex items-center gap-2">
                                            <Calendar size={14} className="text-gray-500" />
                                            <span className="text-gray-300">{shift.date}</span>
                                        </div>
                                    </td>
                                    <td>
                                        <div className="flex items-center gap-2">
                                            <Clock size={14} className="text-gray-500" />
                                            <span className="text-gray-300">{shift.startTime} - {shift.endTime}</span>
                                        </div>
                                    </td>
                                    <td>
                                        <span className="badge bg-indigo-500/10 text-indigo-300 border border-indigo-500/20">
                                            {diff.toFixed(1)} hrs
                                        </span>
                                    </td>
                                    {user?.role === 'admin' && (
                                        <td className="text-right">
                                            <button
                                                onClick={() => handleDelete(shift._id)}
                                                className="p-2 hover:bg-red-500/20 rounded-lg text-red-400 transition-colors"
                                                title="Delete Shift"
                                            >
                                                <Trash2 size={16} />
                                            </button>
                                        </td>
                                    )}
                                </tr>
                            );
                        })}
                    </tbody>
                </table>
            </div>
        </div>
    );
}
