'use client';
import { useAuth } from '../context/AuthContext';
import { LogOut, User } from 'lucide-react';

export default function Navbar() {
    const { user, logout } = useAuth();

    return (
        <nav className="glass-card mb-8 px-6 py-4 flex justify-between items-center rounded-none border-x-0 border-t-0 sticky top-0 z-50">
            <div className="flex items-center gap-3">
                <div className="bg-indigo-500 p-2 rounded-lg">
                    <svg className="w-6 h-6 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z"></path></svg>
                </div>
                <span className="text-xl font-bold tracking-tight text-white">ShiftBoard</span>
            </div>

            <div className="flex items-center gap-6">
                <div className="flex items-center gap-2 text-gray-300">
                    <User size={18} />
                    <span className="text-sm font-medium">{user?.name} <span className={`text-xs ml-1 px-2 py-0.5 rounded-full ${user?.role === 'admin' ? 'bg-indigo-500/20 text-indigo-300' : 'bg-emerald-500/20 text-emerald-300'}`}>{user?.role}</span></span>
                </div>
                <button onClick={logout} className="flex items-center gap-2 text-gray-400 hover:text-white transition-colors text-sm font-medium">
                    <LogOut size={18} />
                    Logout
                </button>
            </div>
        </nav>
    );
}
