'use client';
import { useState, useEffect } from 'react';
import api from '../utils/api';

export default function ShiftForm({ onShiftAdded }) {
    const [employees, setEmployees] = useState([]);
    const [formData, setFormData] = useState({
        employeeId: '',
        date: '',
        startTime: '',
        endTime: ''
    });
    const [error, setError] = useState('');
    const [success, setSuccess] = useState('');
    const [loading, setLoading] = useState(false);

    useEffect(() => {
        const fetchEmployees = async () => {
            try {
                const res = await api.get('/employees');
                setEmployees(res.data);
            } catch (err) {
                console.error("Failed to fetch employees");
            }
        };
        fetchEmployees();
    }, []);

    const handleChange = (e) => {
        setFormData({ ...formData, [e.target.name]: e.target.value });
    };

    const handleSubmit = async (e) => {
        e.preventDefault();
        setError('');
        setSuccess('');
        setLoading(true);

        try {
            await api.post('/shifts', formData);
            setSuccess('Shift assigned successfully!');
            setFormData({ ...formData, date: '', startTime: '', endTime: '' }); // Keep employee selected
            if (onShiftAdded) onShiftAdded();
        } catch (err) {
            setError(err.response?.data?.msg || 'Failed to assign shift');
        } finally {
            setLoading(false);
        }
    };

    return (
        <div className="glass-card p-6 mb-8">
            <h2 className="text-xl font-semibold mb-4 text-white">Assign New Shift</h2>
            {error && <div className="bg-red-500/10 text-red-200 p-3 rounded mb-4 text-sm border border-red-500/20">{error}</div>}
            {success && <div className="bg-green-500/10 text-green-200 p-3 rounded mb-4 text-sm border border-green-500/20">{success}</div>}

            <form onSubmit={handleSubmit} className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-5 gap-4 items-end">
                <div className="lg:col-span-1">
                    <label className="block text-gray-400 text-xs font-bold mb-1">Employee</label>
                    <select
                        name="employeeId"
                        value={formData.employeeId}
                        onChange={handleChange}
                        className="input-field mb-0 py-2.5"
                        required
                    >
                        <option value="">Select Employee</option>
                        {employees.map(emp => (
                            <option key={emp._id} value={emp._id}>{emp.name} ({emp.department})</option>
                        ))}
                    </select>
                </div>
                <div className="lg:col-span-1">
                    <label className="block text-gray-400 text-xs font-bold mb-1">Date</label>
                    <input
                        type="date"
                        name="date"
                        value={formData.date}
                        onChange={handleChange}
                        className="input-field mb-0 py-2.5"
                        required
                    />
                </div>
                <div className="lg:col-span-1">
                    <label className="block text-gray-400 text-xs font-bold mb-1">Start Time</label>
                    <input
                        type="time"
                        name="startTime"
                        value={formData.startTime}
                        onChange={handleChange}
                        className="input-field mb-0 py-2.5"
                        required
                    />
                </div>
                <div className="lg:col-span-1">
                    <label className="block text-gray-400 text-xs font-bold mb-1">End Time</label>
                    <input
                        type="time"
                        name="endTime"
                        value={formData.endTime}
                        onChange={handleChange}
                        className="input-field mb-0 py-2.5"
                        required
                    />
                </div>
                <div className="lg:col-span-1">
                    <button
                        type="submit"
                        className="w-full btn btn-primary py-2.5"
                        disabled={loading}
                    >
                        {loading ? 'Assigning...' : 'Assign Shift'}
                    </button>
                </div>
            </form>
        </div>
    );
}
